  str_n27_15_name = "ST3 - Pernikahan",
  str_n27_1_name_desc = "—",
  str_n27_2_name_desc = "Pernikahan yang kacau menyebabkan dilema bagi Anda, dan pengantin wanita Tara tampaknya menderita amnesia.",
  str_n27_3_name_desc = "Setelah tiba di Lumopolis, Naroxel memberi pasangan itu tugas khusus sebelum memberi mereka stempel persetujuannya — untuk membantu Serikat Kurir menjual perangko edisi terbatas untuk Hari Mahkota Bulan.",
  str_n27_4_name_desc = "Anda pergi ke Umbraton bersama Adonis untuk beristirahat dan bersantai, tetapi secara tidak sengaja mengetahui bahwa Laboratorium Payung Hitam di Illumina mungkin dapat memeriksa Tara dan kondisinya.",
  str_n27_5_name_desc = "Setelah tiba di Illumina, Anda bertemu dengan Dove di Gannon City. Dia berjanji bahwa selama Anda membantunya mengirimkan backlog pengirimannya, dia akan memberi segel pada pasangan itu.",
  str_n27_6_name_desc = "Di Laboratorium Payung Hitam, Jola memberi tahu Anda bahwa dia dapat mencoba membuat penawar racun jika dia memiliki sisik cacing pasir yang langka. Tapi, Adonis berpikir dia tidak punya peluang melawan makhluk seperti itu.",
  str_n27_7_name_desc = "Jeriah memanggil Sable dan Adonis untuk latihan perang, tapi tidak ada yang berani menyerang.",
  str_n27_8_name_desc = "Identitas Sable hampir terungkap di Kota Gannon. Kya berjanji padanya bahwa dia akan membawanya pulang.",
  str_n27_9_name_desc = "—",
  str_n27_10_name_desc = "Pagi-pagi keesokan harinya, Anda mengemasi barang-barang Anda dan bersiap berangkat untuk menemukan cacing pasir merah muda yang langka.",
  str_n27_11_name_desc = "Tepat setelah Anda selesai makan, sekelompok Eclipsites lainnya muncul. Munculnya begitu banyak Eclipsites membuat Jeriah gelisah.",
  str_n27_12_name_desc = "Cacing pasir merah muda sangat licik. Itu menggunakan keuntungan dari medan asalnya untuk memisahkan semua orang dan menempatkan Anda semua dalam bahaya ...",
  str_n27_13_name_desc = "Anda berangkat menuju oasis merah muda yang dipenuhi cacing pasir di kendaraan Jeriah, berharap tidak ada bahaya yang menimpa Kya dan yang lainnya ...",
  str_n27_14_name_desc = "Adonis dan Kya baik-baik saja, tapi dimana Sable?",
  str_n27_15_name_desc = "—",
  str_n27_level_desc_long_1 = "Menjelang Hari Mahkota Bulan, Naroxel mempercayakan Anda dengan tugas khusus: untuk mengawal tunangan temannya dari Gurun Rediesel ke Northland. Dia didampingi oleh seorang anggota senior dari divisi Rediesel Wrench Serikat Kurir bernama Jeriah. Anda segera berangkat, tetapi segalanya tidak berjalan mulus.",
  str_n27_level_desc_long_2 = "Terinspirasi oleh kata-kata Jeriah, Tara memutuskan untuk menguji ketulusan Adonis dengan memalsukan amnesia. Setelah gagal menemukan penawarnya, ramuan psikologis serba guna, Adonis mendengarkan saran Jeriah dan mengajak Tara untuk berpartisipasi dalam perayaan Hari Bulan Mahkota Persatuan Kurir di seluruh benua.",
  str_n27_level_desc_long_3 = "Setelah tiba di Lumopolis, Naroxel meminta pasangan itu untuk menyelesaikan tes segel dengan cara yang relatif manis dan mengharukan—dengan menjual perangko Crown Moon Day, dan dia berharap Anda dan Jeriah akan terus membantu mereka. Tetapi bahkan jika uji segel selesai, itu mungkin tidak cukup untuk menjembatani celah di antara mereka.",
  str_n27_level_desc_long_4 = "Anda membawa Adonis untuk bersantai di Umbraton, tetapi terjerat dalam caper dengan Hachi dan Gin. Setelah menyingkirkan mereka, Anda belajar dari Dina bahwa Anda mungkin bisa pergi ke Laboratorium Payung Hitam untuk memeriksa sendiri kondisi Tara.",
  str_n27_level_desc_long_5 = "Anda menangkap Dove bersembunyi di kantor serikat pekerja, bermalas-malasan dari pekerjaan. Dia dengan santai mengatakan bahwa dia akan mencap segel selama Anda membantu dengan simpanan pesanannya. Anda dan rombongan Anda mulai membantu Dove mengirimkan surat, sementara Kya mengajak Sable untuk mencari petunjuk tentang ingatannya di Kota Gannon.",
  str_n27_level_desc_long_6 = "Anda menuju ke Black Umbrella Laboratories, di mana Jola memberi tahu Anda bahwa dia mungkin bisa membuat penawar jika saja dia memiliki sisik cacing pasir yang langka. Adonis putus asa memikirkannya tetapi tidak siap untuk menyerah. Jeriah percaya bahwa tempat yang tepat untuk memulai adalah dengan mengasah keberaniannya.",
  str_n27_level_desc_long_7 = "Adonis dan Sable mulai bertanding tetapi menemui jalan buntu. Adonis gusar dengan provokasi Jeriah, yang membuatnya memberanikan diri untuk menyerang. Serangan ini tampaknya membangkitkan ingatan tentang gurun di benak Sable. Namun, Jeriah telah mengetahui identitas Sable yang sebenarnya, dan menghadapi Kya.",
  str_n27_level_desc_long_8 = "Kya mengajak Sable untuk membeli makanan, tetapi Sable pingsan karena ingatannya yang melonjak, hampir mengungkap identitasnya. Kya membawanya pergi untuk melarikan diri dari keramaian. Ketika Sable terbangun, dia ingat bahwa dia pernah menjadi seorang Aurorian, ditipu oleh kekasihnya, dan rumahnya sepertinya berada di suatu tempat di Gurun Rediesel.",
  str_n27_level_desc_long_9 = "Anda kembali ke cabang Rediesel Wrench dari Courier Union, berencana untuk memulihkan diri di sini dalam semalam dan memulai lagi. Jeriah pergi untuk memeriksa kondisi kendaraan dan mengemas peralatan sementara Tara menyeret Adonis pergi untuk menyalakan api unggun dan menyiapkan makanan ala Rediesel Wrench.",
  str_n27_level_desc_long_10 = "Keesokan paginya, Anda mengemasi peralatan Anda dan bersiap untuk pergi. Namun, Adonis mengatakan dia tidak banyak tidur berkat dendeng kadal pedas yang dia makan malam sebelumnya. Yang bisa dia lakukan sekarang adalah berusaha menjaga semangatnya dan mengikuti di belakang, tetapi apakah dia benar-benar baik-baik saja?",
  str_n27_level_desc_long_11 = "Setelah mengalahkan dua kelompok Eclipsites secara berurutan, Jeriah yang cerdik menyadari sesuatu yang tidak biasa—Eclipsites ini tidak berperang sama sekali. Bahkan, itu lebih seperti mereka berlari untuk hidup mereka! Saat itu, alasan Eclipsites berlarian dalam hiruk-pikuk akhirnya muncul dengan sendirinya. Itu adalah cacing pasir merah muda yang langka!",
  str_n27_level_desc_long_12 = "Anda terkunci dalam pertempuran yang sulit dengan cacing pasir merah muda. Akhirnya, cacing pasir menggunakan kelicikannya untuk melarikan diri, menimbulkan awan debu dan membawa lari Adonis, Kya, dan Sable. Jeriah mengirim Pembicaranya untuk mencari teman Anda yang hilang, tetapi tidak dapat menemukan mereka. Menghadapi krisis ini, dia akhirnya memutuskan untuk lengah dan meminta bantuan orang-orang di gurun.",
  str_n27_level_desc_long_13 = "Jeriah mengantarmu ke oasis tempat tinggal cacing pasir merah muda. Di sini, Anda menemukan Adonis dan Kya tidak sadarkan diri, tetapi Sable, terbawa oleh cacing pasir, tidak dapat ditemukan. Saat Adonis bangun, Tara mengatakan yang sebenarnya tentang amnesia pura-puranya...",
  str_n27_level_desc_long_14 = "Untuk menemukan Sable, Jeriah mengirimkan Speakernya lagi. Kali ini, Pembicara membawa kembali jejak Sable. Ternyata Sable melawan cacing pasir merah muda untuk melindungi dua Aurorian yang tidak sadarkan diri, dan identitas aslinya bukanlah kerabat Kya...",
  str_n27_level_desc_long_15 = "Setelah banyak lika-liku yang tak terduga, Tara dan Adonis akhirnya lebih mengenal satu sama lain, dengan bantuan Jeriah. Mereka berhasil lulus ujian dan mendapatkan persetujuan dari keluarga mereka. Pada akhirnya, mereka menjadi pasangan yang bahagia. Anda menyelesaikan kepercayaan Naroxel dan menerima hadiahnya—sekarang, saatnya kembali ke Soroz.",
  str_n27_h1_name = "H1 - Kecepatan Melepuh",
  str_n27_h2_name = "H2 - Formasi",
  str_n27_h3_name = "H3 - Persimpangan",
  str_n27_h4_name = "H4 - Putus",
  str_n27_h1_name_desc = "Lebih cepat! Lebih cepat! Kecepatan adalah segalanya! Kita tidak hanya harus berlomba menuju masa depan dengan kecepatan penuh, tetapi kita juga harus melawan musuh yang menyerang kita secara langsung!",
  str_n27_h2_name_desc = "Tampaknya kita akan mendapat bantuan dari pasukan sahabat dalam pertempuran ini, dan mereka tampaknya telah mengambil semacam formasi militer. Mungkin kita bisa menggunakan ini?",
  str_n27_h3_name_desc = "Di mana tiga sisi berpotongan muncul cara untuk menghadapi musuh dari tiga sisi yang berbeda, tetapi di pinggir... potensi \"jalan pintas\" juga muncul dengan sendirinya.",
  str_n27_h4_name_desc = "Medannya rusak dan jurang maut mengelilingi... Meskipun banyak musuh yang tidak terpengaruh oleh kondisi seperti itu, untungnya, Anda memiliki sekutu yang dapat mengatasi kerumitan seperti itu...",
  str_n27_bh1_name = "EX1 - Terang",
